#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.0600325, 0.353874505, 0.07920195], 'basis': [[-0.0, 0.9577986268870093, 0.28744006389743154], [0.1355545199210923, -0.2847869600828468, 0.9489580388487856], [0.9907698885861248, 0.03896379986770443, -0.12983393304874996]], 'axis': [0.28744006389743154, 0.9489580388487856, -0.12983393304874996], 'zmin': -0.03804677749275977, 'zmax': 0.038697563568325, 'profiles': [{'outer': [[-0.040519669765327754, 0.006774547669953287], [-0.0397918419095774, 0.009889942244002645], [-0.038658018148308985, 0.013336913579293532], [-0.03716013151279132, 0.016790304886641277], [-0.03532806457208803, 0.02008610023060263], [-0.033179529150371444, 0.023187762068142017], [-0.03073465228715705, 0.026065269216612442], [-0.02801841310661561, 0.028690043859356116], [-0.025056118553769085, 0.031038176527481826], [-0.02187627354377775, 0.03308690311213854], [-0.02021399087359456, 0.033992638217054505], [-0.01676583201804769, 0.03555510785447199], [-0.013180938001717362, 0.0367738924050282], [-0.00949142283568847, 0.03763806929885108], [-0.005735212725830422, 0.03813905616320392], [-0.001948366302929904, 0.038271524991922115], [0.0018347425765026474, 0.038033658963718756], [0.005575790950736969, 0.03742922403989809], [0.009239014726422766, 0.036463929472019006], [0.01103038758829785, 0.03584830097087708], [0.01451140822027759, 0.034358767094256136], [0.01619258896873905, 0.033488559704229606], [0.019416247584562066, 0.03150856408972781], [0.02242230291989918, 0.029231368961003194], [0.025148800790266948, 0.026722430940842368], [0.027482766470139433, 0.02416119043771006], [0.030015533603475836, 0.02108250094123926], [0.033434562174959194, 0.017382900185949176], [0.03481044289173396, 0.015780825603762], [0.03616489278388928, 0.01405368570732157], [0.03738182291969797, 0.012285524161087287], [0.03843398715088162, 0.01052071332338203], [0.03931298328941689, 0.008796606415127955], [0.04001124277282359, 0.007150862151875585], [0.04051697094854426, 0.00565424237117176], [0.04113514850834082, 0.002909461305600577], [0.04159967683481733, -0.0007066878853057948], [0.041035227704021064, -0.004309368118705556], [0.04034159141248909, -0.007035412467064965], [0.039794031343230105, -0.0085174010853538], [0.039051204473876194, -0.010143303879898294], [0.038124533049355265, -0.011842322123098053], [0.03702472010738334, -0.01357790958946771], [0.03575829840550203, -0.01531145223150904], [0.034356892888209804, -0.017000124358414213], [0.032937457646154154, -0.01856354812287767], [0.029417674207998953, -0.022168024692811428], [0.02566418154833931, -0.026399021702645308], [0.023037497168313804, -0.028912274848451196], [0.02160242991267288, -0.03010304362735732], [0.01853420095303539, -0.03229677002517664], [0.015257179028697075, -0.03418661591952774], [0.01180902017315021, -0.035750043355572116], [0.008223135386931294, -0.036968866869928195], [0.004534606924155391, -0.0378329962563424], [0.0007783810655351652, -0.038333034644953155], [-0.0030094462195550454, -0.0384655420478332], [-0.006791568395734619, -0.03822858631084808], [-0.010532489767602704, -0.03762443941149509], [-0.01419584638671803, -0.0366588657523951], [-0.017746734797279767, -0.03534076034026932], [-0.021150401491224, -0.0336835345587676], [-0.02437405019934813, -0.03170258075600091], [-0.027386468080820618, -0.029418058000575432], [-0.03015967893578956, -0.026850644716551606], [-0.03266544087754401, -0.02402540870493922], [-0.033811259934715815, -0.022524591372385876], [-0.03587380409605184, -0.019364604759490128], [-0.0376135864944995, -0.016019783544437886], [-0.039015111052924725, -0.012525561982996586], [-0.04005349643384227, -0.009049292581125197], [-0.04042661815202891, -0.007408605991015577], [-0.040844578746991905, -0.004852812134902915], [-0.04124968976706161, 0.000438712812789855], [-0.04091745681082283, 0.004044420798692968]], 'holes': []}], 'simplify_tolerance': 4.7886933895886034e-05, 'sketch_entity_count': 183}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
